Scripts.OnLoad:
this:RegisterEvent("PRESTIGE_BENEFIT_CHANGED")
if Prestige_IsBenefitActive(PrestigeBenefitType_AuctionHouse_HideName) then
	AAC_AnonymousSale:SetEnable(true);
else
	AAC_AnonymousSale:SetEnable(false);
end

AAC_AnonymousSale:SetChecked(Prestige_IsAnonymousSale());

Scripts.OnEvent:
if event == "PRESTIGE_BENEFIT_CHANGED" then
	if Prestige_IsBenefitActive(PrestigeBenefitType_AuctionHouse_HideName) then
		AAC_AnonymousSale:SetEnable(true);
	else
		AAC_AnonymousSale:SetEnable(false);
	end

	AAC_AnonymousSale:SetChecked(Prestige_IsAnonymousSale());
end

Scripts.OnEnter:
GameTooltip:SetOwner(this, "ANCHOR_TOP", 0, 0);
--PRESTIGE_BENEFIT_ANONYM
GameTooltip:SetText(TEXT("PRESTIGE_BENEFIT_ANONYM"));

local text = TEXT("PRESTIGE_BENEFIT_ANONYM_DESC_TOOLTIP");
GameTooltip:AddLine(text, 0, 0.75, 0.95, false, PrestigeTooltipWidth);
GameTooltip:AddSeparator();
GameTooltip:AddLine(PRESTIGE_BENEFIT_ANONYM_DESC_TOOLTIP_2, 0, 0.75, 0.95 );

Scripts.OnShow:
                        if AAC.TradingUI and AAC.TradingUI.restoringContents then return end
						this:SetText( "" );
						AAC.Sell.MyOffers_OnTextChanged( this:GetText() )
